// website/test/readme.mjs — the site's README against the things it describes (W1.1).
//
// The README is the only file under `website/` a reader opens first, and it makes four
// kinds of promise: which command installs, which builds and which checks; what is
// generated and where its regeneration command is; that the build needs no network; and
// that a page renders a fact rather than restating it. A promise in prose is a promise
// nothing holds, so every one of them is asserted here against its source — the
// generated file's own header, `package.json`'s own scripts, the generator's own `main`,
// the generated CLI reference — and never against a copy of the string this file writes.
//
// Two of the checks below exist because their absence was a real defect rather than a
// hypothetical one. The Go gate the README printed selected **none** of the site's own
// pins (`-run 'Docs|Lint'` matches no `TestWebsite*` and no `TestCliRef*`), so the
// section that prints it is held to the test functions the site's Go files declare; and
// "everything under `content/` is generated and carries its command on line one" was
// false of the aggregation's JSON output, which has no line to carry a comment on — so
// the two kinds of file are distinguished and each is held to its own property.
//
// The gates section makes one promise of a different kind: it opens by counting the checks it
// lists ("Nine checks run over the **built** artifact …") and then names them, one bullet each.
// A count is a claim like any other, and the one it makes is about the list under it — a gate
// added without the sentence moving leaves the README undercounting itself, which is the defect
// the case below is written for. It is held to the list, and the list to the files.
//
// W0.6's changelog comes with its own test (`changelog.mjs`), and each later task adds
// its own file: `npm run check` runs `test/*.mjs`, so none of them touches this one.

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

// website/test/readme.mjs -> website/test -> website -> the repository root.
const SITE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const REPO_ROOT = path.dirname(SITE_ROOT)

const README_PATH = path.join(SITE_ROOT, 'README.md')
const PACKAGE_PATH = path.join(SITE_ROOT, 'package.json')
const CONFIG_PATH = path.join(SITE_ROOT, 'astro.config.mjs')
const CONTENT_DIR = path.join(SITE_ROOT, 'content')

// The header a generated document carries on its first line. It is read out of the file
// rather than typed here, so the README is held to the command the generator itself
// names: a regeneration command that changes has one place to change.
const GENERATED_HEADER = /^<!--\s*generated by (.+?);\s*do not edit\s*-->/

// The keys `fugaro stats runs --json` prints (internal/cli/stats.go's writeStats), which
// is what makes a JSON file under `content/` the aggregation's output rather than a
// number somebody typed: the sample-window fields, the minimum-sample rule and the
// disclaimer the figures travel with all have to be there.
// The files under `content/` that are written by hand and generated by nothing. The list
// is explicit and lives here, so a generated-looking file cannot become hand-kept by
// being left out of the README: the README's row must say `none: hand-kept` AND the file
// must be named here, or the check fails.
const HAND_KEPT = ['downloads.json']
const HAND_KEPT_MARK = /^none: hand-kept$/

const AGGREGATE_KEYS = ['project', 'since', 'until', 'min_runs', 'recipes', 'totals', 'not_a_promise']

function readme() {
  assert.ok(existsSync(README_PATH), "website/README.md is missing: it is the site directory's own document and W1.1 step 3 writes it")
  return readFileSync(README_PATH, 'utf8')
}

function packageJSON() {
  return JSON.parse(readFileSync(PACKAGE_PATH, 'utf8'))
}

// The generated-files table: `| File | Source | Regenerate with |`, parsed out of the
// README so the Source column — the fact each page renders, which the site's own
// no-restating rule makes load-bearing — can be resolved against the repository.
function generatedFileRows(text) {
  const lines = text.split('\n')
  const start = lines.findIndex((line) => /^\|\s*File\s*\|\s*Source\s*\|\s*Regenerate with\s*\|/.test(line))
  assert.ok(start >= 0, 'the README carries no "| File | Source | Regenerate with |" table')

  const rows = []
  for (const line of lines.slice(start + 2)) {
    if (!line.trim().startsWith('|')) break
    const cells = line.split('|').slice(1, -1).map((cell) => cell.trim())
    assert.equal(cells.length, 3, `the generated-files table row has ${cells.length} cells, want 3: ${line}`)
    const file = /^`([^`]+)`$/.exec(cells[0])
    assert.ok(file, `the table's first cell is not a backticked path: ${cells[0]}`)
    rows.push({ file: file[1], source: cells[1], regenerate: cells[2], handKept: HAND_KEPT_MARK.test(cells[2]) })
  }
  assert.ok(rows.length > 0, 'the generated-files table has no data row')
  return rows
}

// globToRegExp turns the one shell glob the check script uses into the matcher it means,
// so "every test/*.mjs" can be asserted file by file instead of taken on trust.
function globToRegExp(glob) {
  const source = glob
    .replace(/[.+^${}()|[\]\\?]/g, '\\$&')
    .replace(/\*/g, '[^/]*')
  return new RegExp(`^${source}$`)
}

// resolveSource resolves one backticked token from the table's Source column against the
// repository it names, and returns a sentence saying why not when it cannot. Three
// shapes are what a source of a site fact can be:
//
//   - a file: `SECURITY.md` (the root) or a path with a slash and an extension;
//   - a Go package and symbol: `internal/cli.NewRootCmd` (Go's pkg.Symbol), which is a
//     directory holding a file that declares the symbol;
//   - a command: `fugaro stats runs ...`, which has to be a command the generated CLI
//     reference documents.
//
// A token that resolves by none of them is a source nobody can check, which is what a
// fabricated Source column would look like.
function resolveSource(token) {
  const asPath = path.resolve(REPO_ROOT, token)
  if (asPath.startsWith(REPO_ROOT + path.sep) && existsSync(asPath)) {
    if (statSync(asPath).isFile() || token.endsWith('/')) return null
  }

  // `internal/cli.NewRootCmd`: Go's pkg.Symbol, where the package path is everything
  // before the last dot and the part after it is an exported name that some Go file in
  // that directory has to declare. Split at the last dot rather than matched as a regexp:
  // a greedy path group reads `internal/cli` as the directory `cli`.
  const dot = token.lastIndexOf('.')
  const pkgDir = dot > 0 ? token.slice(0, dot) : ''
  const symbolName = dot > 0 ? token.slice(dot + 1) : ''
  if (pkgDir.includes('/') && /^[A-Z][A-Za-z0-9_]*$/.test(symbolName)) {
    const dir = path.resolve(REPO_ROOT, pkgDir)
    if (!dir.startsWith(REPO_ROOT + path.sep) || !existsSync(dir) || !statSync(dir).isDirectory()) {
      return `${pkgDir}/ is not a directory in this repository`
    }
    const decl = new RegExp(`func ${symbolName}\\b`)
    const found = readdirSync(dir)
      .filter((name) => name.endsWith('.go'))
      .some((name) => decl.test(readFileSync(path.join(dir, name), 'utf8')))
    if (found) return null
    return `${symbolName} is not declared in any Go file of ${pkgDir}/`
  }

  if (token.startsWith('go run ./internal/clidoc')) {
    // The generator's real flag set: every stdflag definition in internal/clidoc.
    const dir = path.join(REPO_ROOT, 'internal', 'clidoc')
    const real = new Set()
    for (const name of readdirSync(dir).filter((n) => n.endsWith('.go'))) {
      for (const m of readFileSync(path.join(dir, name), 'utf8').matchAll(/stdflag\.\w+\("([^"]+)"/g)) real.add(m[1])
    }
    const words = token.split(/\s+/).slice(3)
    const bad = words.filter((w) => w.startsWith('-') && !real.has(w.replace(/^-+/, '').split('=')[0]))
    const extra = words.filter((w) => !w.startsWith('-'))
    if (bad.length === 0 && extra.length === 0) return null
    return `internal/clidoc defines no ${[...bad, ...extra].map((f) => `\`${f}\``).join(', ')}`
  }

  if (token.startsWith('fugaro ')) {
    // A shell redirect is not part of the command.
    token = token.split(/\s+>\s*/)[0]
    const reference = readFileSync(path.join(CONTENT_DIR, 'cli-reference.md'), 'utf8')
    // Only <placeholder> words are dropped: a literal -flag must itself appear in the
    // reference, so an invented flag does not resolve.
    const words = token.split(/\s+/).slice(1).filter((word) => !word.startsWith('<'))
    const command = words.filter((word) => !word.startsWith('-')).join(' ')
    if (!reference.includes(command)) return `the generated CLI reference documents no \`${command}\``
    const missing = words.filter((word) => word.startsWith('-') && !reference.includes(word))
    if (missing.length === 0) return null
    return `the generated CLI reference documents no ${missing.map((f) => `\`${f}\``).join(', ')}`
  }

  return `it is not a file, a Go package and symbol, or a command`
}

test('the README names the commands that install, build and check the site', () => {
  const text = readme()
  const pkg = packageJSON()

  for (const command of ['npm ci', 'npm run build', 'npm run check']) {
    assert.ok(text.includes(command), `the README does not name \`${command}\`: a reader who cannot find the three commands cannot build or check the site`)
  }

  // The two scripts the README's commands run, read from package.json, so the README
  // promises the scripts this file has and not a remembered spelling.
  assert.ok(pkg.scripts && pkg.scripts.build, 'package.json defines no build script')
  assert.ok(pkg.scripts.check, 'package.json defines no check script')
})

test('the check script builds the site and then runs every test/*.mjs', () => {
  const pkg = packageJSON()
  const check = pkg.scripts.check
  const build = pkg.scripts.build

  const buildAt = check.indexOf('npm run build')
  const testAt = check.indexOf('node --test')
  assert.ok(buildAt >= 0, `check does not run the build: ${check}`)
  assert.ok(testAt >= 0, `check does not run node --test: ${check}`)
  assert.ok(buildAt < testAt, `check runs the tests before the build, so a test that reads the built artifact would read the previous one: ${check}`)

  // The glob has to be the directory's, not a list: a task that adds a file to test/
  // must be picked up without editing this one (W1.1 step 4). It is read out of the
  // script and turned into the matcher it means, and the matcher is shown to be a
  // matcher before it is applied -- a check that a name "matches" a pattern that matches
  // everything has asserted nothing.
  const glob = /node --test\s+(\S+)/.exec(check)?.[1]
  assert.ok(glob, `check does not pass a glob to node --test: ${check}`)
  const matched = globToRegExp(glob)
  assert.ok(matched.test('test/readme.mjs'), `the matcher for ${glob} does not match test/readme.mjs, so it is not the pattern the script runs`)
  assert.ok(!matched.test('test/nested/deep.mjs'), `the matcher for ${glob} matches a file in a subdirectory, so it is not a single-level glob`)
  assert.ok(!matched.test('test/readme.js'), `the matcher for ${glob} matches a non-.mjs file`)

  const tests = readdirSync(path.join(SITE_ROOT, 'test')).filter((name) => name.endsWith('.mjs'))
  assert.ok(tests.length > 0, 'website/test/ holds no .mjs file, so the glob check is looking at nothing')
  for (const name of tests) {
    assert.ok(matched.test(`test/${name}`), `${name} would not be picked up by check's glob ${glob}`)
  }

  // The build is the site's own gate, and it is astro's: a lockfile-committed install
  // followed by a build that fetches nothing (W1.1 step 2).
  assert.match(build, /astro build/, `the build script does not run astro build: ${build}`)
  assert.match(
    build,
    /ASTRO_TELEMETRY_DISABLED=1/,
    `the build script does not set ASTRO_TELEMETRY_DISABLED=1: astro reports anonymous usage unless it is set, and the site's build is a build that needs no network (W1.1 step 2)`,
  )
})

test('the Go gate the README prints selects the site\'s own tests', () => {
  const text = readme()

  // The command, read out of the README rather than typed here, and then held to the
  // test functions the site's Go files declare. This is the check that would have caught
  // the command this README printed before it: `-run 'Docs|Lint'` selects 53 tests in
  // internal/cli and **not one** of the site's pins, so a reader running it got a green
  // run with every fact the site renders unexecuted.
  const command = /go test[^\n]*?-run '([^']+)'/.exec(text)
  assert.ok(command, 'the README prints no `go test … -run \'…\'` command')
  const pattern = new RegExp(command[1])
  assert.ok(text.includes('./internal/clidoc'), 'the Go gate the README prints does not name ./internal/clidoc, where the generator\'s own tests live')

  // The site's Go test files: the docs_website_* pins in internal/cli, and internal/clidoc's
  // own tests (cliref_test.go / secdoc_test.go), which the reference's pins are split across.
  const cliDir = path.join(REPO_ROOT, 'internal', 'cli')
  const clidocDir = path.join(REPO_ROOT, 'internal', 'clidoc')
  const files = [
    ...readdirSync(cliDir)
      .filter((name) => /^docs_website_.*_test\.go$/.test(name))
      .map((name) => path.join(cliDir, name)),
    ...readdirSync(clidocDir)
      .filter((name) => name.endsWith('_test.go'))
      .map((name) => path.join(clidocDir, name)),
  ]
  assert.ok(files.length >= 4, `only ${files.length} of the site's Go test files were found, so this check is looking at a fraction of the site`)

  const declared = files.flatMap((file) =>
    [...readFileSync(file, 'utf8').matchAll(/^func (Test[A-Za-z0-9_]+)\(/gm)].map((m) => m[1]),
  )
  assert.ok(declared.length >= 15, `the site's Go files declare ${declared.length} tests, which is too few to be the site's pins`)

  // The pattern is a pattern: it must reject something, or "every name matches" is the
  // tautology this whole case exists to replace. The plan's baseline is the control.
  const baseline = new RegExp('Docs|Lint')
  assert.ok(
    declared.some((name) => !baseline.test(name)),
    "the control failed: every test the site declares matches 'Docs|Lint', so this case could not have caught the command it was written for",
  )

  for (const name of declared) {
    assert.ok(pattern.test(name), `${name} is the site's own pin and the Go gate the README prints (${command[1]}) does not select it: a reader running the command the README names gets a green run with this test unexecuted`)
  }
})

// The number words the gates section's opening sentence may count with. A list rather than a
// numeral parser: the README writes its counts as words, and a count this file cannot read is a
// count nothing holds.
const NUMBER_WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve']

test('the gates section counts the gates it lists, and every gate it names is a file', () => {
  const lines = readme().split('\n')

  // The section's own opening sentence, which is where the count is written. It is found by
  // its shape rather than by its position, so a section moved is still the section read.
  const opening = lines.findIndex((line) => /^\w+ checks run over the \*\*built\*\* artifact/.test(line))
  assert.ok(opening >= 0, 'the README has no gates section opening on "… checks run over the **built** artifact"')

  const stated = /^(\w+) checks run over/.exec(lines[opening])
  const count = NUMBER_WORDS.indexOf(stated[1].toLowerCase())
  assert.ok(count >= 0, `the gates section opens with "${stated[1]}", which is not a number this check can read`)

  // The list under it: one bullet per gate, each opening with a backticked `test/*.mjs` and each
  // wrapping onto indented lines — one of the bullets (the budget's) runs to several paragraphs
  // and blank lines of its own. So a bullet is what is counted, an indented or blank line is a
  // bullet's own prose and is passed over, and the list ends at the first line that is neither:
  // the paragraph the section closes with.
  const first = lines.findIndex((line, at) => at > opening && /^- `test\/[\w-]+\.mjs`/.test(line))
  assert.ok(first > opening, 'the gates section lists no gate, so there is no count to hold')
  const gates = []
  for (const line of lines.slice(first)) {
    const gate = /^- `(test\/[\w-]+\.mjs)`/.exec(line)
    if (gate) gates.push(gate[1])
    else if (line.trim() !== '' && !/^\s/.test(line)) break
  }
  assert.equal(new Set(gates).size, gates.length, `the gates section lists a gate twice: ${gates.join(', ')}`)
  for (const gate of gates) {
    assert.ok(existsSync(path.join(SITE_ROOT, gate)), `${gate} is listed as one of the site's gates and is not a file`)
  }

  // The count, against the list it is a count of. A gate added to the list without the sentence
  // moving is a README that undercounts itself, and a gate removed without it moving is one that
  // overcounts: both are the same defect, and it is the defect this case exists for.
  assert.equal(
    gates.length,
    count,
    `the gates section says ${stated[1]} checks run over the built artifact and lists ${gates.length} (${gates.join(', ')}): the count is a fact about the list under it, so the two move together`,
  )
})

test('the README names the Node version package.json pins', () => {
  const text = readme()

  // One value, in two files: engines is what a toolchain enforces, and the README is
  // what a reader follows, so the README carries engines' own string rather than a
  // second spelling of the same rule (W1.1 step 1).
  const engines = packageJSON().engines
  assert.ok(engines && engines.node, 'package.json pins no Node version in engines')
  assert.ok(
    text.includes(engines.node),
    `the README does not carry engines.node's value \`${engines.node}\`: the site's Node version is pinned in both or in neither`,
  )
  assert.match(text, /\bNode\b/, 'the README does not name Node at all')
  // The major line, because that is what a reader installs.
  assert.match(String(engines.node), /^>=22/, `engines.node is ${engines.node}, which this README's text does not describe`)
})

test('the README table and the files under content/ agree, file by file', () => {
  const text = readme()
  const rows = generatedFileRows(text)
  assert.ok(existsSync(CONTENT_DIR), "website/content/ is missing: it is where Part 0 writes the site's generated documents")

  const byPath = new Map(rows.map((row) => [row.file, row]))
  const files = readdirSync(CONTENT_DIR).filter((name) => !name.startsWith('.'))

  // Every file in the directory has a row, and every row's own file is one of them --
  // except a row whose file is generated by an owner-run command that has not been run
  // yet, which is `content/costs.json`'s day-one state and has to be named rather than
  // quietly allowed: the row is what says the file is expected.
  for (const name of files) {
    const rel = `content/${name}`
    assert.ok(byPath.has(rel), `${rel} is not named by the README's generated-files table: a generated file with no row is a file whose regeneration command nobody wrote down`)
  }
  for (const name of HAND_KEPT) {
    assert.ok(files.includes(name), `the hand-kept list names content/${name}, which is not in the directory`)
  }
  for (const row of rows) {
    assert.match(row.file, /^content\//, `the table names ${row.file}, which is not a file under content/`)
  }

  for (const name of files) {
    const rel = `content/${name}`
    const row = byPath.get(rel)
    const body = readFileSync(path.join(CONTENT_DIR, name), 'utf8')

    // A hand-kept file is held to being named on both sides, not to a generator's shape.
    assert.equal(
      row.handKept,
      HAND_KEPT.includes(name),
      `${rel}: the README row's Regenerate cell is "${row.regenerate}" and the hand-kept list is [${HAND_KEPT}]: a file is hand-kept in both places or in neither`,
    )
    if (row.handKept) {
      assert.doesNotThrow(() => JSON.parse(body), `${rel} is hand-kept JSON and does not parse`)
      continue
    }

    if (name.endsWith('.md')) {
      // A document: it says what wrote it on line one, and the README names that command.
      const m = GENERATED_HEADER.exec(body.split('\n', 1)[0])
      assert.ok(m, `${rel} carries no "generated by …; do not edit" header: a generated document says so on its first line, or a reader edits it`)
      assert.ok(
        text.includes(m[1]),
        `the README does not name \`${m[1]}\`, the command ${rel} says generated it: a regeneration command the file names and the README does not is a command nobody runs`,
      )
      assert.ok(
        row.regenerate.includes(m[1]),
        `the table's Regenerate cell for ${rel} is "${row.regenerate}", and the file says ${m[1]}: the two are one value`,
      )

      // And the command is real: the directory it runs from is in this repository and
      // declares a main. A README naming a command that does not exist is worse than one
      // naming none.
      const target = m[1].trim().split(/\s+/).at(-1)
      const dir = path.resolve(REPO_ROOT, target)
      assert.ok(dir.startsWith(REPO_ROOT + path.sep), `${rel} names the command \`${m[1]}\`, which points outside the repository`)
      assert.ok(statSync(dir).isDirectory(), `${rel} names \`${m[1]}\`, and ${target} is not a directory in this repository`)
      const goFiles = readdirSync(dir).filter((f) => f.endsWith('.go'))
      assert.ok(
        goFiles.some((f) => /^func main\(/m.test(readFileSync(path.join(dir, f), 'utf8'))),
        `${rel} names \`${m[1]}\`, and no Go file in ${target} declares a main`,
      )
      continue
    }

    // Machine output: no header is possible, so what makes it generated is its shape.
    assert.ok(
      !body.startsWith('<!--'),
      `${rel} opens with a comment: the aggregation's --json output has no header to carry, so a comment here is either a hand-written file wearing one or a format that is not the command's output`,
    )
    const json = JSON.parse(body)
    for (const key of AGGREGATE_KEYS) {
      assert.ok(
        Object.hasOwn(json, key),
        `${rel} carries no "${key}": the file under content/ is the aggregation's own output, and \`fugaro stats runs --json\` prints ${AGGREGATE_KEYS.join(', ')} (internal/cli/stats.go)`,
      )
    }
    assert.ok(
      /fugaro stats runs --project/.test(row.regenerate),
      `${rel}'s Regenerate cell does not name the aggregation: ${row.regenerate}`,
    )
  }
})

test('every source in the README table resolves to something in this repository', () => {
  const text = readme()
  const rows = generatedFileRows(text)

  // The Source column says which document each generated file is derived from, and the
  // site's own rule ("a page renders a fact; it never restates one") is what makes that
  // column the load-bearing one: it is the fact, and a fact nobody can find is a
  // paraphrase with a citation-shaped string next to it.
  for (const row of rows.filter((r) => !r.handKept)) {
    const tokens = [...row.source.matchAll(/`([^`]+)`/g)].map((m) => m[1])
    assert.ok(tokens.length > 0, `${row.file}'s Source cell names no source at all: ${row.source}`)
    for (const token of tokens) {
      const why = resolveSource(token)
      assert.equal(why, null, `${row.file}'s Source cell names \`${token}\`, and ${why}`)
    }
  }
})

test('every command in the README table Regenerate column resolves, flags included', () => {
  const rows = generatedFileRows(readme())
  for (const row of rows.filter((r) => !r.handKept)) {
    const tokens = [...row.regenerate.matchAll(/`([^`]+)`/g)].map((m) => m[1])
    assert.ok(tokens.length > 0, `${row.file}'s Regenerate cell names no command: ${row.regenerate}`)
    for (const token of tokens) {
      assert.ok(token.startsWith('go run ./internal/clidoc') || token.startsWith('fugaro '), `${row.file}'s Regenerate cell names \`${token}\`, which is neither the generator nor a fugaro command`)
      assert.equal(resolveSource(token), null, `${row.file}'s Regenerate cell names \`${token}\`, and ${resolveSource(token)}`)
    }
  }
})

test('the README names the aggregation that writes the costs the page publishes', () => {
  const text = readme()

  // W0.3's command is owner-run and refused in a coding agent's session, so the README
  // states it as a command the owner runs and never as one the build runs.
  assert.ok(
    text.includes('fugaro stats runs --project'),
    "the README does not name `fugaro stats runs --project`: the caps-and-costs figures are the aggregation's output and a reader has to be able to see where they come from",
  )
  assert.ok(
    text.includes('content/costs.json'),
    "the README does not name website/content/costs.json as the aggregation's published output",
  )

  // The command is the CLI's own, not a remembered spelling: the generated reference is
  // Part 0's record of the command tree, and it is what W1.5's page reads too.
  const reference = readFileSync(path.join(CONTENT_DIR, 'cli-reference.md'), 'utf8')
  assert.ok(reference.includes('stats runs'), 'the generated CLI reference does not document `stats runs`')
  assert.ok(reference.includes('--project'), 'the generated CLI reference does not document `stats runs --project`')
  assert.ok(reference.includes('--json'), "the generated CLI reference does not document the aggregation's --json output")
})

test('the README names the changelog as built at build time, from the release files', () => {
  const text = readme()

  // Nothing is generated into the tree: the changelog's source is docs/releases/ and its
  // builder runs during the build (W0.6, D100), which is why the README has no
  // regeneration command for it and names the two paths a reader needs instead.
  assert.ok(text.includes('docs/releases/'), "the README does not name docs/releases/, the changelog's source of truth")
  assert.ok(
    text.includes('src/lib/changelog.mjs'),
    'the README does not name src/lib/changelog.mjs, the module the build reads the releases with',
  )
  assert.ok(
    existsSync(path.join(SITE_ROOT, 'src', 'lib', 'changelog.mjs')),
    'src/lib/changelog.mjs does not exist, so the README names a module the site does not have',
  )
  assert.ok(
    !existsSync(path.join(CONTENT_DIR, 'changelog.json')),
    'content/changelog.json exists: the changelog is built at build time and never committed, so a copy in the tree is the stale copy D100 exists to prevent',
  )
})

test('the README states the rule that a page renders a fact rather than restating it', () => {
  // The rule every later task is held to, and the one this directory's whole layout
  // follows: data/ and content/ hold the facts, src/ renders them, and no page writes a
  // number, a command or a claim of its own.
  assert.ok(
    readme().includes('A page renders a fact; it never restates one.'),
    'the README does not state the rule this site is written to: "A page renders a fact; it never restates one."',
  )
})

test('the README says the build needs no network', () => {
  // W1.1 step 2: the install needs the network once, and nothing after it does. The
  // origins test (W1.11) holds the built page to it; this holds the README to saying it.
  assert.match(readme(), /no network/i, 'the README does not say the build needs no network')
})

test('the config declares a static output and states an empty integrations list', () => {
  // The config is imported rather than pattern-matched: it is a module, and a comment
  // that mentions integrations is not an integration. The list has to be *stated* -- an
  // omitted one passes every check of its contents and holds nothing.
  return import('../astro.config.mjs').then((mod) => {
    const config = mod.default
    assert.ok(config, 'astro.config.mjs has no default export')
    assert.equal(config.output, 'static', 'the site is static-first (F56): output must be "static"')
    assert.ok(
      Array.isArray(config.integrations),
      'astro.config.mjs does not state an integrations list: the shell ships none, and a rule that holds only while nobody adds a line is not stated',
    )
    assert.equal(
      config.integrations.length,
      0,
      `astro.config.mjs declares ${config.integrations.length} integration(s): the shell ships none, and one that fetches at build time would break the network-free build (W1.1 step 2)`,
    )
  })
})

test("the site's own sources name no third-party font or script host", () => {
  // Fonts are self-hosted (D106): no Google Fonts, no CDN, no embed. W1.11 asserts this
  // over the built HTML, and this is the same rule over the sources the shell adds --
  // README.md is not scanned, because prose about the rule is not a request.
  const banned = /fonts\.(googleapis|gstatic)\.com|use\.typekit\.net|cdn\.jsdelivr\.net|unpkg\.com/i
  const roots = ['src', 'public', 'astro.config.mjs', 'package.json', 'tsconfig.json']

  const walk = (rel) => {
    const abs = path.join(SITE_ROOT, rel)
    if (!existsSync(abs)) return []
    if (!statSync(abs).isDirectory()) return [rel]
    return readdirSync(abs).flatMap((name) => walk(path.join(rel, name)))
  }

  const files = roots.flatMap(walk)
  assert.ok(files.length > 0, 'the scan found no site source at all, so it proves nothing')
  for (const rel of files) {
    const text = readFileSync(path.join(SITE_ROOT, rel), 'utf8')
    const m = banned.exec(text)
    assert.equal(m, null, `${rel} names ${m && m[0]}: the site loads nothing from a third party, and its fonts are self-hosted (D106, Global Constraint 8)`)
  }
})

test('every dependency is pinned exactly, and the lockfile resolves from the npm registry alone', () => {
  const pkg = packageJSON()

  // An exact version per dependency: a caret is a range, and a range means the tree
  // `npm ci` installs today is not the tree it installs in a month. The lockfile is
  // committed and the direct dependencies are pinned, so an install is one tree.
  const deps = { ...(pkg.dependencies ?? {}), ...(pkg.devDependencies ?? {}) }
  const names = Object.keys(deps)
  assert.ok(names.length > 0, 'package.json declares no dependency, so the site has no toolchain')
  for (const name of names) {
    assert.match(
      deps[name],
      /^\d+\.\d+\.\d+$/,
      `package.json pins ${name} at "${deps[name]}": the site's dependencies are exact versions, so the lockfile and the manifest cannot disagree about what is installed`,
    )
  }

  // Where every package in the tree comes from, package by package: the lockfile's own
  // `resolved` URLs, all of them, and the integrity hash npm verifies each tarball
  // against. A dependency arriving from a git URL, a tarball on a third party's host or a
  // path in somebody's checkout is a build that runs code this project did not choose --
  // and one that would make `npm ci` fetch from somewhere other than the registry.
  const lock = JSON.parse(readFileSync(path.join(SITE_ROOT, 'package-lock.json'), 'utf8'))
  const packages = Object.entries(lock.packages ?? {}).filter(([key]) => key !== '')
  assert.ok(packages.length > 10, `the lockfile records ${packages.length} packages, which is too few to be this site's dependency tree`)
  for (const [key, entry] of packages) {
    if (!entry.resolved) continue // a workspace link or the root entry: nothing to fetch
    const url = new URL(entry.resolved)
    assert.equal(
      url.host,
      'registry.npmjs.org',
      `${key} resolves from ${url.host}: the site's packages come from the npm registry and from nowhere else (no git URL, no third-party host, no local path)`,
    )
    assert.ok(entry.integrity, `${key} carries no integrity hash: an install that cannot verify what it fetched is not a pinned install`)
  }
})

test('.gitignore keeps the dependency tree and the build output out of the tree', () => {
  const ignore = path.join(SITE_ROOT, '.gitignore')
  assert.ok(existsSync(ignore), 'website/.gitignore is missing: a committed node_modules or dist/ is a build output in the repository')
  const lines = readFileSync(ignore, 'utf8').split('\n').map((l) => l.trim())

  for (const entry of ['node_modules/', 'dist/', '.astro/']) {
    assert.ok(lines.includes(entry), `website/.gitignore does not ignore ${entry}`)
  }
  // The lockfile is the opposite of an ignored file and is deliberately not matched
  // here: it is committed, so the install is reproducible from the pinned versions.
  assert.ok(
    !lines.some((l) => l === 'package-lock.json' || l === '*.json'),
    'website/.gitignore ignores the lockfile: the pinned dependency tree is committed, so `npm ci` installs what the build was checked with',
  )
})

test('the README claims about docs/pending-workflows/, firebase.json and the deploy script are literally true', () => {
  const text = readme()
  assert.ok(!/Nothing under `docs\/pending-workflows\/`/.test(text), 'the README says nothing is staged under docs/pending-workflows/, but other pending workflows are committed there')
  const staged = path.join(REPO_ROOT, 'docs', 'pending-workflows')
  // The README says what docs/pending-workflows/ holds, and the claim is checked in both directions
  // rather than as a bare count: a workflow staged there that the README does not name is a
  // pending change nobody was told about, and a name in the README that is not staged is an
  // instruction to copy in a file that is not there. The count is asserted too, so that
  // "holds one pending workflow" cannot survive a second file arriving beside it.
  //
  // The count is written as a word and read back as a number, so that the sentence is the
  // only thing a copy-in has to update: copying a staged file in and `git rm`-ing it leaves
  // the directory with none, and "now holds no pending workflow" is then an edit to the
  // sentence rather than to this test as well.
  //
  // The owner copied the website's two manual workflows (#566) into .github/workflows/ and removed
  // the staged copies, so none of them is pending and the real files exist.
  const flat = text.replace(/\s+/g, ' ')
  const words = { no: 0, one: 1, two: 2, three: 3 }
  const said = flat.match(/now holds (no|one|two|three) pending workflows?/)
  assert.ok(said, 'the README no longer says how many workflows docs/pending-workflows/ holds, as "now holds <no|one|two|three> pending workflow(s)"')
  // The console's two workflows are the one exception, and it is not a pending one: the owner copied
  // both into .github/workflows/ and their staged copies are kept on purpose (the Go docs tests assert
  // byte-identity), so each staged file must be exactly the one that runs.
  const keptStaged = ['console-release.yml', 'console-tests.yml']
  const yamls = existsSync(staged) ? readdirSync(staged).filter((n) => /\.ya?ml$/i.test(n)).sort() : []
  const pending = yamls.filter((n) => !keptStaged.includes(n))
  const claimed = [...flat.matchAll(/`docs\/pending-workflows\/([\w.-]+\.ya?ml)`/g)].map((m) => m[1])
  assert.deepEqual([...new Set(claimed)].sort(), pending, 'the README and docs/pending-workflows/ disagree: the README names exactly the pending workflows and no others (a staged file it does not name, or a named file that is not staged)')
  assert.equal(
    words[said[1]],
    pending.length,
    `the README says "${said[0]}" and docs/pending-workflows/ holds ${pending.length} pending workflow file(s) (${pending.join(', ') || 'none'}): update the sentence`,
  )
  for (const name of yamls.filter((n) => keptStaged.includes(n))) {
    const real = path.join(REPO_ROOT, '.github', 'workflows', name)
    assert.ok(existsSync(real), `docs/pending-workflows/${name} is staged but .github/workflows/${name} is missing, so it is pending and the README says none is`)
    assert.ok(
      readFileSync(real).equals(readFileSync(path.join(staged, name))),
      `docs/pending-workflows/${name} differs from .github/workflows/${name}: a staged copy that is not the running file is a pending change, and the README says none is`,
    )
  }
  assert.ok(/console-tests\.yml/.test(text) && /console-release\.yml/.test(text), 'the README does not say why the console\'s two workflows are still under docs/pending-workflows/')
  for (const name of ['website-preview.yml', 'website-promote.yml']) {
    assert.ok(existsSync(path.join(REPO_ROOT, '.github', 'workflows', name)), `.github/workflows/${name} is missing: the README says the owner copied it in`)
  }
  // firebase.json landed ahead of W2.1 with scripts/deploy-website.sh, and the README says so.
  assert.ok(existsSync(path.join(REPO_ROOT, 'firebase.json')), 'firebase.json is missing: the README says the hosting configuration is at the repository root')
  assert.ok(/`firebase\.json`/.test(text) && /scripts\/deploy-website\.sh/.test(text), 'the README does not describe firebase.json and scripts/deploy-website.sh')
  assert.ok(!existsSync(path.join(REPO_ROOT, '.firebaserc')), '.firebaserc is committed: the README says the project is passed on the command line')
  const deploy = existsSync(staged) ? readdirSync(staged).filter((n) => /deploy/i.test(n)) : []
  assert.deepEqual(deploy, [], 'a deploy workflow is staged: the README says it is W2.1\'s and not yet there')
})
